 function mesh(geo,mat,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
 function box(parent,mat,x,y,z,sx,sy,sz,r=0){let m=mesh(new THREE.BoxGeometry(sx,sy,sz),mat,parent,x,y,z);if(r)m.rotation.y=r;return m}
-function sphere(parent,mat,x,y,z,sx,sy,sz){return mesh(new THREE.SphereGeometry(1,20,16),mat,parent,x,y,z).scale.set(sx,sy,sz)}
+function sphere(parent,mat,x,y,z,sx,sy,sz){const m=mesh(new THREE.SphereGeometry(1,20,16),mat,parent,x,y,z);m.scale.set(sx,sy,sz);return m}
 function cylinder(parent,mat,x,y,z,rt,rb,h,segments=12){return mesh(new THREE.CylinderGeometry(rt,rb,h,segments),mat,parent,x,y,z)}
 function capsule(parent,mat,x,y,z,r,h){return mesh(new THREE.CapsuleGeometry(r,h,4,10),mat,parent,x,y,z)}
 function lineTube(parent,points,mat,r=.025){const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)));return mesh(new THREE.TubeGeometry(curve,24,r,8,false),mat,parent)}

